// W1 · Analista de Leads — tarea atómica: validar y calificar un lead.
// Determinístico: cero tokens, misma entrada => misma salida.
const RAMOS = {
  'Automotor': 'marca, modelo y año del vehículo',
  'Hogar / Combinado Familiar': 'tipo de vivienda',
  'Vida': 'edad o capital asegurado',
  'Accidentes Personales': 'actividad o edad',
  'Comercio / Integral': 'rubro del comercio',
  'ART': 'cantidad de empleados',
};

const i = $input.first().json;
const limpiar = (v) => (v ?? '').toString().trim();

if (!limpiar(i.session_id)) {
  // Error de contrato: dispara la salida de contingencia del Worker
  throw new Error('Contrato inválido: falta session_id');
}

const ramo = limpiar(i.ramo);
const ramoValido = Object.prototype.hasOwnProperty.call(RAMOS, ramo);
const bien = limpiar(i.bien);
const contacto = limpiar(i.contacto);

const email = (contacto.match(/[\w.+-]+@[\w-]+\.[\w.-]+/) || [null])[0];
const digitos = (email ? contacto.replace(email, '') : contacto).replace(/\D/g, '');
const telefono = digitos.length >= 8 ? digitos : null;
const tieneContacto = Boolean(email || telefono);

const faltantes = [];
if (!limpiar(i.nombre)) faltantes.push('nombre');
if (!tieneContacto) faltantes.push('teléfono o email');
if (!limpiar(i.localidad)) faltantes.push('localidad');
if (!bien) faltantes.push(ramoValido ? RAMOS[ramo] : 'ramo y bien a asegurar');

// Criterio heredado del M1: con ramo identificado ya se deriva, no se espera a tener todo.
let temperatura = 'FRIO';
if (ramoValido && bien && tieneContacto) temperatura = 'CALIENTE';
else if (ramoValido && (bien || tieneContacto)) temperatura = 'TIBIO';

return [{
  json: {
    status: 'success',
    data: {
      ramo: ramoValido ? ramo : 'NO_IDENTIFICADO',
      bien,
      nombre: limpiar(i.nombre),
      email: email ?? '',
      telefono: telefono ?? '',
      localidad: limpiar(i.localidad),
      temperatura,
      faltantes,
      notificable: ramoValido,
    },
  },
}];
